export function getArtistHref(artist: {
  handle: string;
  requestedHandle?: string;
  profile: string;
}): { href: string; isInternal: boolean } {
  const h = (artist.handle || '').toLowerCase();
  const req = (artist.requestedHandle || '').toLowerCase();
  const internal = RESIDENT_ARCHIVE_MAP[h] || RESIDENT_ARCHIVE_MAP[req];
  if (internal) {
    return { href: internal, isInternal: true };
  }
  return { href: artist.profile, isInternal: false };
}

export function formatFollowers(count: number): string {
  if (!count) return 'X / Twitter';
  if (count >= 1_000_000) return `${(count / 1_000_000).toFixed(1)}M followers`;
  if (count >= 1_000) return `${Math.round(count / 1_000)}K followers`;
  return `${count} followers`;
}

